param([string]$Boom='target/release/boom.exe',[string]$ExistingRun='',[string]$Runtime='.boom/assembly-runtime-v70/boom-runtime.dll')
$ErrorActionPreference='Stop';$sha=(Get-FileHash $Boom).Hash.ToLowerInvariant()
$root=if($ExistingRun){[IO.Path]::GetFullPath($ExistingRun)}else{Join-Path (Get-Location) ('.boom/coder-java-tests/'+[guid]::NewGuid().ToString('N'))};[IO.Directory]::CreateDirectory($root)|Out-Null
$base=Join-Path ((Get-Content .boom/latest-server-jdk-base.txt -Raw).Trim()) jdk-base.json
if(-not $ExistingRun){& $Boom compile-locked-program --lock .boom/locks/server.json --jdk-base $base --entry-class java/lang/StringConcatHelper --method mix --descriptor '(JLjava/lang/String;)J' --output "$root/program" --assemble > "$root/compile.json" 2> "$root/compile.err";if($LASTEXITCODE -ne 0){Get-Content "$root/compile.err" -Tail 10;throw 'Original coder caller compilation failed'}}
& D:/Dev/Java/jdk-21/bin/javac.exe --release 21 -proc:none -d "$root/classes" java/reference/CoderReference.java;if($LASTEXITCODE -ne 0){throw 'Coder reference javac failed'}
$cases=[Collections.Generic.List[string]]::new();foreach($bits in @('0','1','7ffffffe','7fffffff','80000000','ffffffff','100000000','100000001','7fffffff00000000','ffffffffffffffff')){foreach($text in @('','61','d800','dc00','d801:dc00','0:61:ffff','61:62:63','null')){$cases.Add($bits+' '+$text)}}
$info=[Diagnostics.ProcessStartInfo]::new();$info.FileName='D:/Dev/Java/jdk-21/bin/java.exe';$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardInput=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true
foreach($arg in @('-Xmx128m','-XX:-CompactStrings','--add-opens=java.base/java.lang=ALL-UNNAMED','-cp',"$root/classes",'CoderReference')){$info.ArgumentList.Add($arg)}
foreach($key in @('JAVA_TOOL_OPTIONS','_JAVA_OPTIONS','JDK_JAVA_OPTIONS','CLASSPATH')){$info.Environment.Remove($key)|Out-Null}
$jvm=[Diagnostics.Process]::new();$jvm.StartInfo=$info
try{if(-not $jvm.Start()){throw 'Coder JVM did not start'};$stdout=$jvm.StandardOutput.ReadToEndAsync();$stderr=$jvm.StandardError.ReadToEndAsync();$jvm.StandardInput.Write(($cases -join "`n")+"`n");$jvm.StandardInput.Close();if(-not $jvm.WaitForExit(30000)){$jvm.Kill($true);throw 'Coder reference timeout'};if($jvm.ExitCode -ne 0){throw $stderr.GetAwaiter().GetResult()};$expected=@($stdout.GetAwaiter().GetResult().Split("`n",[StringSplitOptions]::RemoveEmptyEntries)|ForEach-Object{$_.TrimEnd("`r")})}finally{$jvm.Dispose()}
$p=Get-Content "$root/program/program.json" -Raw|ConvertFrom-Json;$binding=@($p.string_storage|Where-Object property -eq Coder);if($binding.Count -ne 1 -or $binding[0].value -ne 1 -or $binding[0].caller.binary_name -ne 'java.lang.StringConcatHelper'){throw 'Coder original call-site proof missing'}
$ids=[uint32[]]@($p.object_layouts|ForEach-Object class_id);$names=[string[]]@($p.object_layouts|ForEach-Object{$_.class_name.Replace('/','.')});$message=@(@($p.exception_runtime.factories|Where-Object kind -eq 4)[0].fields|Where-Object name -eq detailMessage)[0].offset;$overflow=@($p.symbols|Where-Object method -eq checkOverflow)[0].id
Add-Type -Path tests/host/CoderProbe.cs
$actual=[BoomCoderProbe]::Run($p.compilation.dll,[IO.Path]::GetFullPath($Runtime),$cases.ToArray(),$ids,$names,[uint32]$message,[uint32]$overflow)
if($actual.Count -ne $expected.Count){throw 'Coder reference count differs'};for($i=0;$i -lt $actual.Count;$i++){if($actual[$i] -cne $expected[$i]){throw "Coder mismatch $($cases[$i]): expected=$($expected[$i]) actual=$($actual[$i])"}}
if((Get-FileHash $Boom).Hash.ToLowerInvariant() -ne $sha){throw 'Coder compiler changed'}
$r=[ordered]@{compiler_sha256=$sha;runtime_language='assembly';compiled_images=1;JVM_cases=$cases.Count;JVM_reference_CompactStrings=$false;original_StringConcatHelper_mix_and_checkOverflow_executed=$true;original_String_coder_body_executed=$false;VM_UTF16_coder_value=1;VM_String_fixtures_used=$true;null_and_overflow_Throwable_and_source_checked=$true;passed=$true;game_started=$false;world_created=$false;full_game_ready=$false;run_directory=$root};$json=$r|ConvertTo-Json;[IO.File]::WriteAllText("$root/result.json",$json,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText('.boom/latest-coder-java-test.txt',$root);Write-Output $json
exit 0
